/**
 * Sprint 32 MVP benchmark: ten tasks a developer would delegate to an AI IDE.
 *
 * FROZEN before any model run (see docs/sprints/SPRINT_32_PRODUCT_CONVERGENCE.md for the commit and hash).
 * Do not edit after results are observed. Oracles are hidden: they run from a directory outside the
 * workspace and are never shown to the agent. Reference solutions live in s32-reference.ts and only prove
 * that each task is feasible and that each oracle rejects the untouched fixture.
 */
import { fileURLToPath } from "node:url"
import type { CodingTask } from "./coding-tasks.ts"

const L = (...lines: string[]) => lines.join("\n") + "\n"
const TS_PKG = JSON.stringify({ name: "fixture", private: true, type: "module", scripts: { test: "node --experimental-strip-types --test" } }, null, 2) + "\n"
const JS_PKG = JSON.stringify({ name: "fixture", private: true, type: "module", scripts: { test: "node --test" } }, null, 2) + "\n"
const TSC = fileURLToPath(new URL("../../../node_modules/typescript/bin/tsc", import.meta.url))
const tsconfig = (include: readonly string[]) => JSON.stringify({ compilerOptions: { strict: true, noEmit: true, allowImportingTsExtensions: true, module: "ESNext", moduleResolution: "Bundler", target: "ES2022", skipLibCheck: true, types: [] }, include }, null, 2) + "\n"
const testHead = 'import assert from "node:assert/strict"\nimport test from "node:test"\n'

/** Node oracle with helpers: fail(), src(), has(word), typecheck(), and a mutant runner for test-quality checks. */
function oracle(body: string, opts: { typecheck?: boolean } = {}): CodingTask["oracle"] {
  return {
    kind: "node",
    script: [
      "import { readFileSync, cpSync, writeFileSync, mkdtempSync, rmSync, existsSync } from 'node:fs'",
      "import { execFileSync, spawnSync } from 'node:child_process'",
      "import { tmpdir } from 'node:os'",
      "import { join } from 'node:path'",
      "const fail = (m) => { console.log(m); process.exit(1) }",
      "const src = (f) => readFileSync('WS/' + f, 'utf8')",
      "const has = (f, w) => new RegExp('(?<![\\\\w$])' + w + '(?![\\\\w$])').test(src(f))",
      "const nodeTests = (dir) => spawnSync(process.execPath, ['--experimental-strip-types', '--test'], { cwd: dir, encoding: 'utf8', timeout: 60000 })",
      "const mutantKilled = (file, from, to) => { const dir = mkdtempSync(join(tmpdir(), 'ovsc-mutant-')); try { cpSync('WS/', dir, { recursive: true, filter: (p) => !p.includes('/.git') }); const text = readFileSync(join(dir, file), 'utf8'); if (!text.includes(from)) fail('mutation anchor missing in ' + file); writeFileSync(join(dir, file), text.replace(from, to)); return nodeTests(dir).status !== 0 } finally { rmSync(dir, { recursive: true, force: true }) } }",
      ...(opts.typecheck ? [`try { execFileSync(process.execPath, [${JSON.stringify(TSC)}, '--noEmit', '-p', 'WS/tsconfig.json'], { stdio: 'pipe' }) } catch (e) { fail('typecheck: ' + String(e.stdout).slice(0, 400)) }`] : []),
      body,
    ].join("\n") + "\n",
  }
}

